"""SQLAlchemy ORM models for cached transformations and generated payloads."""

import uuid
from datetime import datetime
from typing import Final

from sqlalchemy import DateTime, MetaData, String, Text, Uuid, func
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column, registry

# Hex SHA-256 digests: a fixed-size key indexes the same way on SQLite and PostgreSQL,
# whereas PostgreSQL caps B-tree entries on raw text at roughly 2.7 kB.
HASH_LENGTH: Final = 64

# Deterministic constraint names, so autogenerated migrations match what the database holds.
NAMING_CONVENTION: Final = {
    "ix": "ix_%(column_0_label)s",
    "uq": "uq_%(table_name)s_%(column_0_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


class Base(DeclarativeBase):
    # timestamptz on PostgreSQL; SQLite has no timezone type and stores naive UTC.
    registry = registry(
        metadata=MetaData(naming_convention=NAMING_CONVENTION),
        type_annotation_map={datetime: DateTime(timezone=True)},
    )


class Transformation(Base):
    """One cached transformer result, keyed by the hash of the exact input string."""

    __tablename__ = "transformations"

    input_hash: Mapped[str] = mapped_column(String(HASH_LENGTH), primary_key=True)
    # Lookups return results keyed by this column, and it lets the hash be recomputed.
    input: Mapped[str] = mapped_column(Text)
    output: Mapped[str] = mapped_column(Text)
    created_at: Mapped[datetime] = mapped_column(server_default=func.now())


class Payload(Base):
    """A generated payload; unique by output so a repeated payload keeps its first id."""

    __tablename__ = "payloads"

    # Random rather than derived from the hash, so public ids stay opaque and survive any
    # future change to the hashing scheme.
    id: Mapped[uuid.UUID] = mapped_column(Uuid, primary_key=True, default=uuid.uuid4)
    output_hash: Mapped[str] = mapped_column(String(HASH_LENGTH), unique=True)
    output: Mapped[str] = mapped_column(Text)
    created_at: Mapped[datetime] = mapped_column(server_default=func.now())
